// ExamPage.js
import React, { useState, useEffect } from "react";
import './ExamPage.css';

const ExamPage = () => {
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutes timer (300 seconds)
  const [answers, setAnswers] = useState({
    q1: "",
    q2: "",
    q3: "",
  });

  useEffect(() => {
    if (timeLeft === 0) return;

    const timer = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [timeLeft]);

  const handleChange = (e) => {
    setAnswers({
      ...answers,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Exam submitted! Your answers have been saved.");
    // Add exam submission logic here
  };

  return (
    <div className="exam-container">
      <h2>Exam</h2>
      <div className="timer">
        <p>Time Left: {Math.floor(timeLeft / 60)}:{timeLeft % 60}</p>
      </div>

      <form onSubmit={handleSubmit} className="exam-form">
        <div className="question">
          <label>1. What is 2 + 2?</label>
          <input
            type="text"
            name="q1"
            value={answers.q1}
            onChange={handleChange}
            required
          />
        </div>

        <div className="question">
          <label>2. What is the capital of France?</label>
          <input
            type="text"
            name="q2"
            value={answers.q2}
            onChange={handleChange}
            required
          />
        </div>

        <div className="question">
          <label>3. Who was the first president of the United States?</label>
          <input
            type="text"
            name="q3"
            value={answers.q3}
            onChange={handleChange}
            required
          />
        </div>

        <button type="submit" className="submit-btn">Submit Exam</button>
      </form>
    </div>
  );
};

export default ExamPage;
